import math
class FinetuneWatchdog:
    def __init__(self, patience=3, delta_threshold=0.005):
        self.patience = patience
        self.delta_threshold = delta_threshold
        self.best_val_loss = float('inf')
        self.best_step = None
        self.counter = 0
    def update(self, step, val_loss):
        if math.isnan(val_loss):
            return 'CRITICAL_ABORT'
        if val_loss <= self.best_val_loss - self.delta_threshold:
            self.best_val_loss = val_loss
            self.best_step = step
            self.counter = 0
        else:
            self.counter += 1
        return 'EARLY_STOP_SIGNAL' if self.should_stop() else None
    def should_stop(self):
        return self.counter >= self.patience
